class Constant:
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

    @classmethod
    def items(cls):
        return [(key, value) for key, value in cls.__dict__.items() if not key.startswith('__')]

    @classmethod
    def keys(cls):
        return [key for key, value in cls.__dict__.items() if not key.startswith('__')]

    @classmethod
    def values(cls):
        return [value for key, value in cls.__dict__.items() if not key.startswith('__')]

    @classmethod
    def to_dict(cls):
        return {key: value for key, value in cls.__dict__.items() if not key.startswith('__')}

    @classmethod
    def collection(cls, sort_by=None):
        if sort_by:
            return sorted([child for child in cls.__subclasses__() if hasattr(child, sort_by)], key=lambda x: getattr(x, sort_by))
        else:
            return [child for child in cls.__subclasses__()]

    @classmethod
    def get(cls, key, value, multi=False):
        if multi:
            return [child for child in cls.collection() if getattr(child, key) == value]
        else:
            return next((child for child in cls.collection() if getattr(child, key) == value), None)
