```javascript
function bubbleSort(arr) {
  let sorted;
  do {
    sorted = false;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i] > arr[i + 1]) {
        [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
        sorted = true;
      }
    }
  } while (sorted);

  return arr;
}

