import os
import zipfile
from datetime import datetime

def append_text_to_file(directory, filename):
    try:
        with open(f"{directory}/{filename}", "a") as file:
            file.write(f"\n\n--Appended by script at {datetime.now()}--")
            print(f"Text appended to {filename}")
    except (FileNotFoundError, IOError) as e:
        print(f"Error occurred while writing to {filename}: {str(e)}")

def compress_directory(directory):
    try:
        with zipfile.ZipFile(f"{directory}.zip", "w") as zipf:
            for root, dirs, files in os.walk(directory):
                for file in files:
                    zipf.write(os.path.join(root, file))
        print(f"Directory {directory} compressed successfully")
    except IOError as e:
        print(f"Error occurred while compressing directory: {str(e)}")

def append_text_and_compress(directory):
    try:
        for filename in os.listdir(directory):
            append_text_to_file(directory, filename)
        compress_directory(directory)
    except FileNotFoundError as e:
