```python
def first(gram, term):
    first_set = []
    if term not in gram:
        return [term]
    for rule in gram[term]:
        if rule[0] not in gram:
            first_set.append(rule[0])
        else:
            first_set += first(gram, rule[0])
    return first_set

def follow(gram, term, firsts):
    follow_set = []
    for rule in gram:
        for production in gram[rule]:
            if term in production:
                idx = production.index(term)
                if idx+1 != len(production):
                    follow_set += firsts[production[idx+1]] if production[idx+1] in firsts else [production[idx+1]]
                elif rule != term:
                    follow_set += follow(gram, rule, firsts)
                else:
                    follow_set += ["$"]
    return list(set(follow_set))

# Example usage
gram = {
    "E": ["E+T", "T"],
    "T": ["T*F", "F"],
    "F": ["(E)", "id"]
}

firsts = {}
for non_terminal in gram:
    firsts[non_terminal] = first(gram, non_terminal)
    print(f'First({non_terminal}):', firsts[non_terminal])

follows = {}
for non_terminal in gram:
    follows[non_terminal] = follow(gram, non_terminal, firsts)
    print(f'Follow({non_terminal}):', follows[non_terminal])
```
