def determine_fencing_winner(fencer_a_scores, fencer_b_scores):
    fencer_a_total = sum(fencer_a_scores)
    fencer_b_total = sum(fencer_b_scores)

    if fencer_a_total > fencer_b_total:
        return "Fencer A"
