        return "Fencer B"
    else:
        return "Tie"

def average_points_per_game(points):
    if not points:
        return 0.0
    total_points = sum(points)
    num_games = len(points)
    average = total_points / num_games
    return round(average, 2)

def calculate_total_hours(hours_worked):
    total_hours = 0
    for hours in hours_worked:
        total_hours += hours
    return total_hours

